class Solution {
public:
    int latestTimeCatchTheBus(vector<int>& buses, vector<int>& passengers, int capacity) {
        sort(buses.begin(), buses.end());
        sort(passengers.begin(), passengers.end());
        unordered_set<int> times(passengers.begin(), passengers.end());
        int j = 0, m = passengers.size();
        bool filled = false;
        int lastBoarded = 0;
        for (int b : buses) {
            int c = capacity;
            while (j < m && passengers[j] <= b && c > 0) {
                lastBoarded = passengers[j];
                j++; c--;
            }
            filled = (c == 0);
        }
        int ans = filled ? lastBoarded - 1 : buses.back();
        while (times.count(ans)) ans--;
        return ans;
    }
};

