class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);
        Set<Integer> times = new HashSet<>();
        for (int p : passengers) times.add(p);
        int j = 0, m = passengers.length;
        boolean filled = false;
        int lastBoarded = 0;
        for (int b : buses) {
            int c = capacity;
            while (j < m && passengers[j] <= b && c > 0) {
                lastBoarded = passengers[j];
                j++; c--;
            }
            filled = (c == 0);
        }
        int ans = filled ? lastBoarded - 1 : buses[buses.length - 1];
        while (times.contains(ans)) ans--;
        return ans;
    }
}

