var latestTimeCatchTheBus = function(buses, passengers, capacity) {
    buses.sort((a, b) => a - b);
    passengers.sort((a, b) => a - b);
    const times = new Set(passengers);
    let j = 0;
    const m = passengers.length;
    let filled = false, lastBoarded = 0;
    for (const b of buses) {
        let c = capacity;
        while (j < m && passengers[j] <= b && c > 0) {
            lastBoarded = passengers[j];
            j++; c--;
        }
        filled = (c === 0);
    }
    let ans = filled ? lastBoarded - 1 : buses[buses.length - 1];
    while (times.has(ans)) ans--;
    return ans;
};
